with filtered_transactions as (select * from transactions where txn_type = 'FEE'), TxnCohortSummary as (select case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end txn_cohort, sum(amount) total_amount from filtered_transactions group by case when year(txn_time) < 2024 then 'before_2024' when year(txn_time) = 2024 then '2024' else 'after_2024' end) select * from TxnCohortSummary where total_amount < 16000 order by total_amount desc, txn_cohort limit 5;
